import type { QueryResult } from '@dynatrace-sdk/client-query';

import type { QueryColumn } from './convert-to-columns.js';
import { convertToColumns } from './convert-to-columns.js';
import { convertToTimeseries } from './convert-to-timeseries.js';
import type { Timeseries } from '../charts/core/types/timeseries.js';
import {
  ColumnOptions,
  TableColumn,
} from '../tables/types/shared-table-types.js';

export interface DQLResultConverterBaseProps {
  queryResult: QueryResult;
}

export interface DQLResultConverterTableProps {
  convertTo: 'column';

  /** Function providing options to be applied to columns e.g. `return {ratioWidth: 1}` */
  columnOptionsFn?: (column: TableColumn) => Partial<ColumnOptions>;

  children: (data: QueryColumn[]) => JSX.Element;
}

export interface DQLResultConverterTimeseriesProps {
  convertTo: 'timeseries';

  children: (data: Timeseries[]) => JSX.Element;
}

export type DQLResultConverterProps = DQLResultConverterBaseProps &
  (DQLResultConverterTableProps | DQLResultConverterTimeseriesProps);

/**
 * Provides converted queryResult to the children as a render prop.
 */
export function DQLResultConverter(props: DQLResultConverterProps) {
  switch (props.convertTo) {
    case 'column': {
      return props.children(
        convertToColumns(props.queryResult.types, props.columnOptionsFn),
      );
    }
    case 'timeseries': {
      return props.children(
        convertToTimeseries(props.queryResult.records, props.queryResult.types),
      );
    }
  }
}
